import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../core/app_controller.dart';
import '../widgets/common.dart';

class StatementScreen extends StatelessWidget{const StatementScreen({super.key});@override Widget build(BuildContext context){final app=context.watch<AppController>();final total=app.operations.fold<num>(0,(s,e)=>s+(num.tryParse('${e['amount']??0}')??0));return Scaffold(appBar:AppBar(title:const Text('كشف الحساب')),body:RefreshIndicator(onRefresh:app.refreshWalletAndReports,child:ListView(padding:const EdgeInsets.all(12),children:[PageCard(child:Column(children:[const Text('الرصيد الحالي',style:TextStyle(fontSize:11,color:Colors.black54)),Text('${app.walletBalance.toStringAsFixed(2)} ر.ي',style:const TextStyle(fontSize:27,fontWeight:FontWeight.w900,color:AppColors.burgundy)),const SizedBox(height:3),Text('إجمالي مبالغ العمليات المعروضة: ${total.toStringAsFixed(2)} ر.ي',style:const TextStyle(fontSize:10))])),const SizedBox(height:10),if(app.operations.isEmpty)const PageCard(child:Text('لا توجد حركات.',textAlign:TextAlign.center)) else ...app.operations.map((e)=>Padding(padding:const EdgeInsets.only(bottom:6),child:PageCard(child:Row(children:[const Icon(Icons.swap_horiz,color:AppColors.blue),const SizedBox(width:8),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${e['service']??'عملية'}',style:const TextStyle(fontSize:11,fontWeight:FontWeight.w900)),Text('${e['created_at']??''}',style:const TextStyle(fontSize:9,color:Colors.black45))])),Text('${e['amount']??0} ${e['currency']??'YER'}',style:const TextStyle(fontWeight:FontWeight.w900,fontSize:11))])))])));}}
